import re

# Function to parse price from 32nds format
def convert_price(price_str):
    if not price_str or price_str == '-':
        return None
    parts = price_str.split('.')
    if len(parts) != 2:
        return None
    try:
        dollars = int(parts[0])
        cents_32 = int(parts[1])
        return dollars + cents_32/32
